  // together must always pay more than clearing the same rows one at a time; otherwise there
  // is no reason to build a stack.
  var LINE_SCORES = [0, 100, 300, 500, 800];
  var SOFT_DROP_POINTS = 1; // per cell moved down by the player
  var HARD_DROP_POINTS = 2; // per cell dropped'''
assert s.count(old)==1; s=s.replace(old,new)
old='''      case "softDrop": tryMove(1, 0); break;
      case "hardDrop":
        while (tryMove(1, 0)) {}
        lockPiece();'''
new='''      case "softDrop":
        if (tryMove(1, 0)) score += SOFT_DROP_POINTS;
        break;
      case "hardDrop":
        while (tryMove(1, 0)) score += HARD_DROP_POINTS;
        lockPiece();'''
assert s.count(old)==1; s=s.replace(old,new)
open(p,'w').write(s)
EOF
