import { createRequire } from 'module';
const require = createRequire(process.cwd() + '/');
let pw; try { pw = require('playwright'); } catch { pw = await import(require('child_process').execSync('npm root -g').toString().trim() + '/playwright/index.js'); }
const b = await pw.chromium.launch(); const pg = await b.newPage();
await pg.goto('file:///Users/vmysla/src/ab-study/arms/tetris-rep-control-02/control/index.html');
const r = await pg.evaluate(() => {
  const T = window.__tetris, out = {};
  // soft drop: O spawns rows 0-1, 3 soft drops = 3 points; gravity scores nothing
  T.newGame(['O','O']); T.input('softDrop'); T.input('softDrop'); T.input('softDrop'); T.tick(2);
  out.soft = T.getState().score;
  // hard drop from spawn: O rows 0-1 falls to 18-19 = 18 cells = 36
  T.newGame(['O','O']); T.input('hardDrop'); out.hard = T.getState().score;
  // soft drop against floor scores nothing
  T.newGame(['O','O']); T.input('hardDrop'); const s0 = T.getState().score;
  // double clear: rows 18,19 full except cols 4,5; O fills them
  const rows = Array(20).fill(''); rows[18] = 'IIII..IIII'; rows[19] = 'IIII..IIII'; rows[17] = 'T.........';
  T.newGame(['O','I']); T.setBoard(rows); T.input('hardDrop');
  const st = T.getState();
  out.double = { score: st.score, lines: st.lines, board: T.getBoard().slice(17),
    shown: document.querySelector('[data-testid=lines]').textContent };
  // triple at level 2: 500*2
  T.newGame(['I','O']); const r2 = Array(20).fill('');
  for (let i = 17; i < 20; i++) r2[i] = 'IIIIIIIII.';
  T.setBoard(r2); T.input('rotate'); T.input('right'); T.input('right'); T.input('right'); T.input('right');
  out.pre = T.getState().current.cells;
  return out;
});
console.log(JSON.stringify(r, null, 1)); await b.close();
EOF
